import{_ as a,o as t,c as i,al as r}from"./chunks/framework.7vp1BMOE.js";const m=JSON.parse('{"title":"On-Screen Display (OSD)","description":"","frontmatter":{},"headers":[],"relativePath":"en/peripherals/osd.md","filePath":"en/peripherals/osd.md"}'),o={name:"en/peripherals/osd.md"};function s(d,e,n,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="on-screen-display-osd" tabindex="-1">On-Screen Display (OSD) <a class="header-anchor" href="#on-screen-display-osd" aria-label="Permalink to &quot;On-Screen Display (OSD)&quot;">​</a></h1><p>An <strong>On-Screen Display (OSD)</strong> overlays flight telemetry — battery, altitude, GPS, RSSI, attitude, etc. — onto a pilot&#39;s video feed. OSDs are commonly used in FPV and long-range flying so the pilot can see live flight data without looking away from the video.</p><p>PX4 supports three distinct OSD mechanisms, each targeting a different class of video system:</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Use case</th><th>Transport</th><th>Runs on FC?</th></tr></thead><tbody><tr><td><a href="#msp-osd">MSP OSD</a></td><td>Digital FPV air units and video goggles that speak Betaflight MSP (e.g. DJI O3/O4, Walksnail, HDZero, Caddx Vista)</td><td>Serial, MSPv1</td><td>Yes — <a href="./../modules/modules_driver#msp-osd"><code>msp_osd</code></a> driver</td></tr><tr><td><a href="#atxxxx-analog-osd">ATXXXX Analog OSD</a></td><td>Legacy analog video with an on-board MAX7456/ATXXXX overlay chip (e.g. OmnibusF4SD)</td><td>SPI to on-board chip</td><td>Yes — <a href="./../modules/modules_driver#atxxxx"><code>atxxxx</code></a> driver</td></tr><tr><td><a href="#mavlink-osd">MAVLink OSD</a></td><td>MAVLink-aware ground stations and displays that render their own OSD from telemetry (e.g. Yaapu on EdgeTX/OpenTX, Skydroid, mLRS HUDs)</td><td>Serial, MAVLink</td><td>No — streams MAVLink; the display renders the OSD</td></tr></tbody></table><p>Which one you use is determined by your video hardware, not by PX4 preference. If you&#39;re unsure, start with your video system&#39;s documentation and match the OSD mechanism it expects.</p><h2 id="msp-osd" tabindex="-1">MSP OSD <a class="header-anchor" href="#msp-osd" aria-label="Permalink to &quot;MSP OSD&quot;">​</a></h2><p><strong>MSP (MultiWii Serial Protocol) OSD</strong> is the mechanism used by digital FPV systems (DJI, Walksnail, HDZero) and by many digital goggles/air units to render telemetry over the pilot&#39;s video feed. PX4 implements the subset of MSP used for OSD telemetry, matching what Betaflight and INAV send.</p><p>The <a href="./../modules/modules_driver#msp-osd"><code>msp_osd</code></a> driver converts uORB topics (battery, GPS, attitude, etc.) to MSP packets and sends them out a serial port at 115200 baud.</p><h3 id="supported-displays" tabindex="-1">Supported displays <a class="header-anchor" href="#supported-displays" aria-label="Permalink to &quot;Supported displays&quot;">​</a></h3><p>PX4 currently sends a subset of MSP messages. Reliably-working display items include:</p><ul><li>Craft name and flight mode / arming state</li><li>Average cell voltage, current draw, mAh consumed</li><li>GPS latitude, longitude, satellite count, ground speed</li><li>Home distance</li><li>Altitude (from GNSS / baro)</li><li>Roll / pitch angle</li><li>RSSI</li><li>Crosshairs toggle</li></ul><p>Some items in <a href="./../advanced_config/parameter_reference#OSD_SYMBOLS"><code>OSD_SYMBOLS</code></a> are reserved but not yet implemented — see the parameter&#39;s <code>(unused)</code> bit labels. For feature-completeness work, see the tracking issues on GitHub.</p><h3 id="hardware-setup" tabindex="-1">Hardware setup <a class="header-anchor" href="#hardware-setup" aria-label="Permalink to &quot;Hardware setup&quot;">​</a></h3><ol><li>Connect the digital air unit&#39;s MSP / telemetry input to a free UART on the flight controller (TX → RX, RX → TX, GND → GND).</li><li>Power the air unit from its own BEC or a VTX power pad — most air units expect 5 V or battery voltage, not autopilot 5 V.</li><li>Note which PX4 serial device the UART maps to on your board (e.g. <code>TELEM2</code> → <code>/dev/ttyS2</code>). See <a href="./../hardware/serial_port_mapping">Serial Port Mapping</a>.</li></ol><h3 id="firmware-requirements" tabindex="-1">Firmware requirements <a class="header-anchor" href="#firmware-requirements" aria-label="Permalink to &quot;Firmware requirements&quot;">​</a></h3><p>The <code>msp_osd</code> driver is included in the default build for most modern Pixhawk and FPV-oriented boards (e.g. <code>px4_fmu-v5x</code>, <code>px4_fmu-v6x</code>, <code>ark_fpv</code>, <code>cuav_7-nano</code>, <code>micoair_h743*</code>). If your board does not include it by default, enable it via <a href="./../hardware/porting_guide_config#px4-menuconfig-setup">board config</a>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">boar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boardconfig</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># drivers → OSD → msp_osd</span></span></code></pre></div><p>Then rebuild and flash.</p><h3 id="px4-configuration" tabindex="-1">PX4 configuration <a class="header-anchor" href="#px4-configuration" aria-label="Permalink to &quot;PX4 configuration&quot;">​</a></h3><ol><li>Assign the selected serial port to MSP OSD with <a href="./../advanced_config/parameter_reference#MSP_OSD_CONFIG"><code>MSP_OSD_CONFIG</code></a>.</li><li>Set the matching <code>SER_&lt;PORT&gt;_BAUD</code> to <code>115200</code>.</li><li>Reboot.</li><li>Tune the display via the <a href="./../advanced_config/parameter_reference#osd"><code>OSD_*</code> parameters</a>: <ul><li><a href="./../advanced_config/parameter_reference#OSD_SYMBOLS"><code>OSD_SYMBOLS</code></a> — bitmask selecting which items appear.</li><li><a href="./../advanced_config/parameter_reference#OSD_CH_POS_VER"><code>OSD_CH_POS_VER</code></a> — vertical position of the crosshairs.</li><li><a href="./../advanced_config/parameter_reference#OSD_CH_POS_HOR"><code>OSD_CH_POS_HOR</code></a> — horizontal position of the crosshairs.</li><li><a href="./../advanced_config/parameter_reference#OSD_LOG_LEVEL"><code>OSD_LOG_LEVEL</code></a> — minimum severity for on-screen warnings.</li><li><a href="./../advanced_config/parameter_reference#OSD_SCROLL_RATE"><code>OSD_SCROLL_RATE</code></a> / <a href="./../advanced_config/parameter_reference#OSD_DWELL_TIME"><code>OSD_DWELL_TIME</code></a> — scrolling of long messages.</li><li><a href="./../advanced_config/parameter_reference#OSD_RC_STICK"><code>OSD_RC_STICK</code></a> — forward RC sticks to the VTX when disarmed, so you can navigate the VTX menu.</li></ul></li></ol><h3 id="worked-examples" tabindex="-1">Worked examples <a class="header-anchor" href="#worked-examples" aria-label="Permalink to &quot;Worked examples&quot;">​</a></h3><ul><li><a href="./../frames_plane/reptile_dragon_2#msp-osd-module">Reptile Dragon 2 &gt; msp_osd Module</a> — end-to-end wiring and configuration for a Caddx Vista build.</li><li><a href="./../frames_plane/turbo_timber_evolution">Turbo Timber Evolution</a> — references the same setup pattern.</li></ul><h2 id="mavlink-osd" tabindex="-1">MAVLink OSD <a class="header-anchor" href="#mavlink-osd" aria-label="Permalink to &quot;MAVLink OSD&quot;">​</a></h2><p>Some OSDs render their own overlay directly from the MAVLink telemetry stream — the flight controller simply streams MAVLink at a rate the display can parse. PX4 exposes this via a dedicated MAVLink stream profile.</p><p>To use a MAVLink OSD:</p><ol><li>Choose an unused MAVLink instance (<a href="./../peripherals/mavlink_peripherals#default_ports"><code>MAV_X_CONFIG</code></a>) and assign it to the serial port connected to the display.</li><li>Configure the mode of the selected MAVLink instance with <a href="./mavlink_peripherals#MAV_X_MODE"><code>MAV_X_MODE</code></a> by setting it to <strong><code>OSD</code></strong>. The <code>OSD</code> mode uses a built-in rate table tuned for low-bandwidth OSD consumption.</li><li>Set the matching <code>SER_&lt;PORT&gt;_BAUD</code> to the baud rate the display expects.</li></ol><p>The stream content is fixed (defined in <code>src/modules/mavlink/mavlink_main.cpp</code>) and cannot be customised from parameters. See <a href="./mavlink_peripherals">MAVLink Peripherals (GCS/OSD/Gimbal/Camera/Companion)</a> for the full MAVLink-side configuration.</p><h2 id="atxxxx-analog-osd" tabindex="-1">ATXXXX Analog OSD <a class="header-anchor" href="#atxxxx-analog-osd" aria-label="Permalink to &quot;ATXXXX Analog OSD&quot;">​</a></h2><p>The <a href="./../modules/modules_driver#atxxxx"><code>atxxxx</code></a> driver targets boards with an on-board MAX7456 / ATXXXX chip that overlays characters onto an analog video stream (PAL or NTSC). This was common on older F4-class FCs such as OmnibusF4SD and is largely superseded by digital systems.</p><p>No external wiring is required on boards that include the chip; to enable it, set <a href="./../advanced_config/parameter_reference#OSD_ATXXXX_CFG"><code>OSD_ATXXXX_CFG</code></a> to <code>1</code> (NTSC) or <code>2</code> (PAL) and reboot.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../advanced_config/parameter_reference#osd">Parameter Reference &gt; OSD</a> — all OSD parameters.</li><li><a href="./mavlink_peripherals">MAVLink Peripherals (GCS/OSD/Gimbal/Camera/Companion)</a> — MAVLink serial configuration.</li><li><a href="./serial_configuration">Serial Port Configuration</a> — assigning modules to UARTs.</li><li><a href="./../modules/modules_driver#msp-osd"><code>msp_osd</code> module reference</a> — CLI usage and source.</li></ul>`,32)])])}const u=a(o,[["render",s]]);export{m as __pageData,u as default};
